-- EXP03 original saved-email outcome; forward-only atomic source/ACL guarded carrier.
-- Production baseline and lower predecessors re-read before publication; applied history preserved.
-- Compiled from verified native source-only exports, never from customer data.
-- One atomic DO: all original source/ACL prerequisites before writes, exact final
-- source/metadata readback, same-head replay and rollback on any drift/failure.
DO $exp03_saved_outcome$
DECLARE definitions jsonb := $e03_definitions$[{"acl":"{postgres=X/postgres}","owner":"postgres","definer":true,"full_md5":"421eac815ac3fbc86b90cbbd2b3461d8","settings":["search_path=pg_catalog, public"],"signature":"_lead_reply_record_send(uuid,uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public._lead_reply_record_send(_approval_id uuid, _operation_id uuid, _actor uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n  _uuid       constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';\n  _active     uuid;\n  _tenant     uuid;\n  _ap         public.paige_pending_approvals%ROWTYPE;\n  _act        public.paige_actions%ROWTYPE;\n  _msg        public.messages%ROWTYPE;\n  _state      text;\n  _gs         jsonb;\n  _raw        text;\n  _prior_op   text;\n  _prior_st   text;\n  _named_action uuid;\nBEGIN\n  IF _actor IS NULL OR (auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM _actor) THEN\n    RAISE EXCEPTION 'LEAD_REPLY_FORBIDDEN: sign in to record a reply' USING ERRCODE = '42501';\n  END IF;\n  IF _approval_id IS NULL OR _operation_id IS NULL THEN\n    RAISE EXCEPTION 'LEAD_REPLY_INVALID: an approval and a send operation are required' USING ERRCODE = '22023';\n  END IF;\n\n  -- The actor's active business: the JWT caller's resolved one, or (service path) the actor's profile.\n  _active := CASE WHEN auth.uid() IS NOT NULL THEN public.current_user_tenant_id()\n                  ELSE (SELECT p.active_tenant_id FROM public.profiles p WHERE p.user_id = _actor) END;\n\n  -- Authorization FIRST, on an unlocked read. One refusal for \"no such approval\" and \"not yours\", so\n  -- another business's approval ids are neither confirmed to exist nor lockable by an outsider.\n  SELECT p.tenant_id INTO _tenant FROM public.paige_pending_approvals p WHERE p.id = _approval_id;\n  IF _tenant IS NULL\n     OR _tenant IS DISTINCT FROM _active\n     OR NOT EXISTS (\n          SELECT 1 FROM auth.users u\n           WHERE u.id = _actor AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until <= now()))\n     OR NOT EXISTS (\n          SELECT 1 FROM public.tenant_members m\n           WHERE m.tenant_id = _tenant AND m.user_id = _actor\n             AND m.status = 'active' AND m.role IN ('owner', 'admin')) THEN\n    RAISE EXCEPTION 'LEAD_REPLY_FORBIDDEN: only an owner or admin of this business can record its replies'\n      USING ERRCODE = '42501';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM public.tenants t WHERE t.id = _tenant AND t.status IN ('trial', 'active', 'past_due')) THEN\n    RAISE EXCEPTION 'LEAD_REPLY_WORKSPACE_UNAVAILABLE: this business is not active, so its replies cannot be recorded'\n      USING ERRCODE = '42501';\n  END IF;\n\n  -- Stabilize actor facts before PPA -> action -> message, matching native admission.\n  PERFORM public._comms_email_actor(_actor,_tenant);\n  -- Only now, as a proven owner/admin of the approval's business, take the row lock.\n  SELECT * INTO _ap FROM public.paige_pending_approvals WHERE id = _approval_id FOR UPDATE;\n  IF _ap.id IS NULL OR _ap.tenant_id IS DISTINCT FROM _tenant THEN\n    RAISE EXCEPTION 'LEAD_REPLY_FORBIDDEN: only an owner or admin of this business can record its replies'\n      USING ERRCODE = '42501';\n  END IF;\n\n  -- Lock every own backlink before message, including the strict legacy accepted-lead class.\n  PERFORM 1 FROM public.paige_actions a WHERE a.approval_id=_ap.id AND a.tenant_id=_ap.tenant_id ORDER BY a.id FOR UPDATE;\n  -- The reply action: named by the approval AND pointing back at it, in the same business.\n  _raw := btrim(_ap.metadata->>'action_id');\n  BEGIN _named_action:=nullif(_raw,'')::uuid;\n  EXCEPTION WHEN invalid_text_representation THEN _named_action:=NULL; END;\n  IF _named_action IS NOT NULL THEN\n    SELECT * INTO _act FROM public.paige_actions a\n     WHERE a.id = _named_action AND a.approval_id = _ap.id AND a.tenant_id = _ap.tenant_id FOR UPDATE;\n  END IF;\n  IF _act.id IS NULL OR (_act.action_kind NOT IN ('owner.lead_followup','client.followup','owner.followup_email') AND NOT coalesce(_act.action_kind='comms-draft-reply' AND coalesce(_act.payload->>'channel_type','email')='email'\n    AND EXISTS(SELECT 1 FROM public.messages s WHERE s.tenant_id=_ap.tenant_id AND s.contact_id=_act.contact_id\n      AND s.action_id=_act.id AND s.channel_type='email' AND s.direction='outbound'\n      AND s.meta->>'source'='comms-draft-reply'\n      AND s.meta#>>'{comms_email_binding,operation_id}'=_operation_id::text\n      AND s.meta#>>'{comms_email_binding,approval_id}'=_ap.id::text\n      AND s.meta#>>'{comms_email_binding,actor_user_id}'=_actor::text\n      AND s.meta#>>'{comms_email_binding,governance,draft_source,message_id}'=s.id::text),false)) OR _act.contact_id IS NULL THEN\n    RAISE EXCEPTION 'LEAD_REPLY_WRONG_KIND: only a drafted reply to a new lead is recorded here' USING ERRCODE = '22023';\n  END IF;\n\n  _prior_op := lower(btrim(_ap.metadata#>>'{governed_send,operation_id}'));\n\n  IF _ap.status = 'approved' THEN\n    IF _prior_op = _operation_id::text THEN\n      RETURN jsonb_build_object('ok', true, 'state', 'provider_accepted', 'delivery_confirmed', false,\n        'approval_id', _ap.id, 'message_id', _ap.metadata#>>'{governed_send,message_id}',\n        'operation_id', _operation_id, 'replayed', true);\n    END IF;\n    RAISE EXCEPTION 'LEAD_REPLY_ALREADY_RECORDED: this reply was already recorded as sent by another send'\n      USING ERRCODE = '55000';\n  END IF;\n  IF _ap.status IS DISTINCT FROM 'pending' THEN\n    RAISE EXCEPTION 'LEAD_REPLY_NOT_PENDING: this reply is no longer waiting to be sent' USING ERRCODE = '55000';\n  END IF;\n\n  -- An earlier, different send of this reply that has not finished (or finished accepted but was not\n  -- recorded yet) blocks recording another: two copies of one reply must never both count.\n  IF _prior_op ~ _uuid AND _prior_op IS DISTINCT FROM _operation_id::text THEN\n    SELECT m.meta#>>'{comms_email_binding,state}' INTO _prior_st\n      FROM public.messages m\n     WHERE m.meta ? 'comms_email_binding'\n       AND m.meta#>>'{comms_email_binding,operation_id}' = _prior_op\n       AND m.tenant_id = _ap.tenant_id;\n    IF _prior_st IN ('prepared', 'dispatching', 'unknown', 'provider_accepted') THEN\n      RAISE EXCEPTION 'LEAD_REPLY_PRIOR_SEND_UNRESOLVED: an earlier send of this reply has not been resolved yet'\n        USING ERRCODE = '55000',\n              DETAIL  = format('prior_operation_id=%s prior_state=%s', _prior_op, _prior_st),\n              HINT    = 'Record the earlier send again to pick up its outcome; a new send can be recorded once it has failed.';\n    END IF;\n  END IF;\n\n  -- The governed send for this operation, in this business, to this lead. The operation_id is unique\n  -- across messages (messages_comms_email_operation, partial to meta ? 'comms_email_binding' — the\n  -- predicate below lets the lookup use it), so this is at most one row.\n  SELECT * INTO _msg FROM public.messages m\n   WHERE m.meta ? 'comms_email_binding'\n     AND m.meta#>>'{comms_email_binding,operation_id}' = _operation_id::text\n     AND m.tenant_id = _ap.tenant_id\n     AND m.contact_id = _act.contact_id\n     AND m.channel_type = 'email' AND m.direction = 'outbound' FOR UPDATE;\n  IF _msg.id IS NULL THEN\n    RETURN jsonb_build_object('ok', false, 'state', 'not_found', 'delivery_confirmed', false,\n      'approval_id', _ap.id, 'operation_id', _operation_id);\n  END IF;\n  -- The send was prepared for THIS reply: an accepted email to the same lead that the door prepared for\n  -- another approval, or for none (chat, support), is never this reply's proof.\n  IF lower(btrim(_msg.meta#>>'{comms_email_binding,approval_id}')) IS DISTINCT FROM _ap.id::text THEN\n    RAISE EXCEPTION 'LEAD_REPLY_NOT_THIS_APPROVAL: this email was not sent as this reply, so it cannot be recorded as its send'\n      USING ERRCODE = '42501';\n  END IF;\n  IF (_act.action_kind<>'owner.lead_followup' OR _msg.meta#>>'{comms_email_binding,origin_action_id}' IS NOT NULL)\n   AND (_msg.meta#>>'{comms_email_binding,origin_action_id}' IS DISTINCT FROM _act.id::text\n    OR _msg.meta#>>'{comms_email_binding,origin_action_kind}' IS DISTINCT FROM _act.action_kind\n    OR (SELECT count(*) FROM public.paige_actions a WHERE a.approval_id=_ap.id)<>1) THEN\n    RAISE EXCEPTION 'COMMS_EMAIL_ORIGIN_BINDING_CHANGED' USING ERRCODE='42501';\n  END IF;\n  -- The person recording is the person who sent it: a send is never claimed by someone else.\n  IF lower(_msg.meta#>>'{comms_email_binding,actor_user_id}') IS DISTINCT FROM _actor::text THEN\n    RAISE EXCEPTION 'LEAD_REPLY_NOT_YOUR_SEND: this send was made by another person, so only they can record it'\n      USING ERRCODE = '42501';\n  END IF;\n\n  _state := _msg.meta#>>'{comms_email_binding,state}';\n  _gs := jsonb_build_object('message_id', _msg.id, 'operation_id', _operation_id, 'state', _state, 'recorded_at', now());\n\n  IF _state = 'provider_accepted' THEN\n    UPDATE public.paige_pending_approvals SET\n      status              = 'approved',\n      reviewed_by_user_id = _actor,\n      reviewed_at         = now(),\n      sent_at             = COALESCE(_msg.sent_at, now()),\n      metadata            = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('governed_send', _gs)\n    WHERE id = _ap.id;\n    UPDATE public.clients SET last_contacted_at = now()\n     WHERE id = _act.contact_id AND tenant_id = _ap.tenant_id;\n    RETURN jsonb_build_object('ok', true, 'state', _state, 'delivery_confirmed', false,\n      'approval_id', _ap.id, 'message_id', _msg.id, 'operation_id', _operation_id);\n  END IF;\n\n  IF _state IN ('prepared', 'dispatching', 'unknown') THEN\n    UPDATE public.paige_pending_approvals SET\n      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('governed_send', _gs)\n    WHERE id = _ap.id;\n  END IF;\n\n  -- failed | refused (and any state this function does not know) leave the approval as it was.\n  RETURN jsonb_build_object('ok', false, 'state', COALESCE(_state, 'unknown'), 'delivery_confirmed', false,\n    'approval_id', _ap.id, 'message_id', _msg.id, 'operation_id', _operation_id);\nEND;\n$function$\n","before_md5":"c676f19e07d01760390d022df3c739f8"},{"acl":"{postgres=X/postgres}","owner":"postgres","definer":true,"full_md5":"3838aa7063844f200e6ef7e7c71c6858","settings":["search_path=pg_catalog, public"],"signature":"paige_guard_send_approval_requires_governed_send()","definition":"CREATE OR REPLACE FUNCTION public.paige_guard_send_approval_requires_governed_send()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n  _uuid      constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';\n  _ids       uuid[] := ARRAY[]::uuid[];\n  _kinds     text[];\n  _raw       text;\n  _gs        jsonb;\n  _mid       text;\n  _op        text;\n  _msg       public.messages%ROWTYPE;\n  _tenant    uuid;\n  _old_action uuid; _new_action uuid; _origin uuid; _bound public.messages%ROWTYPE;\nBEGIN\n  IF TG_OP='UPDATE' THEN\n    BEGIN _old_action:=nullif(btrim(OLD.metadata->>'action_id'),'')::uuid;\n    EXCEPTION WHEN invalid_text_representation THEN _old_action:=NULL; END;\n    BEGIN _new_action:=nullif(btrim(NEW.metadata->>'action_id'),'')::uuid;\n    EXCEPTION WHEN invalid_text_representation THEN _new_action:=NULL; END;\n    -- The updating PPA lock precedes its exact actions and messages. Never update messages here:\n    -- ordinary JWT callers remain subject to the incumbent governed-message write guard.\n    PERFORM 1 FROM public.paige_actions a\n     WHERE a.tenant_id=OLD.tenant_id AND a.approval_id=OLD.id\n     ORDER BY a.id FOR UPDATE;\n    FOR _bound IN SELECT m.* FROM public.messages m\n     WHERE m.tenant_id=OLD.tenant_id AND m.meta ? 'comms_email_binding'\n      AND lower(m.meta#>>'{comms_email_binding,approval_id}')=OLD.id::text\n     ORDER BY m.id FOR UPDATE\n    LOOP\n      IF _bound.meta#>>'{comms_email_binding,state}' IN ('prepared','dispatching','unknown','provider_accepted') THEN\n        IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id\n         OR NEW.contact_id IS DISTINCT FROM OLD.contact_id OR _new_action IS DISTINCT FROM _old_action THEN\n          RAISE EXCEPTION 'COMMS_EMAIL_ORIGIN_BINDING_CHANGED' USING ERRCODE='42501';\n        END IF;\n        IF NEW.metadata->'governed_send' IS DISTINCT FROM OLD.metadata->'governed_send'\n         AND NEW.metadata->'governed_send' IS NOT NULL AND NEW.metadata->'governed_send'<>'null'::jsonb\n         AND (NEW.metadata#>>'{governed_send,operation_id}' IS DISTINCT FROM _bound.meta#>>'{comms_email_binding,operation_id}'\n          OR NEW.metadata#>>'{governed_send,message_id}' IS DISTINCT FROM _bound.id::text) THEN\n          RAISE EXCEPTION 'COMMS_EMAIL_ORIGIN_BINDING_CHANGED' USING ERRCODE='42501';\n        END IF;\n        IF NEW.metadata->'governed_send' IS DISTINCT FROM OLD.metadata->'governed_send'\n         AND OLD.metadata->'governed_send' IS NOT NULL AND OLD.metadata->'governed_send'<>'null'::jsonb\n         AND (NEW.metadata->'governed_send' IS NULL OR NEW.metadata->'governed_send'='null'::jsonb) THEN\n          RAISE EXCEPTION 'COMMS_EMAIL_ORIGIN_BINDING_CHANGED' USING ERRCODE='42501';\n        END IF;\n        IF NEW.status IN ('rejected','skipped') AND NEW.status IS DISTINCT FROM OLD.status\n         AND (_bound.meta#>>'{comms_email_binding,state}' IN ('dispatching','unknown','provider_accepted')\n          OR coalesce((_bound.meta#>>'{comms_email_binding,attempts}')::int,0)>0) THEN\n          RAISE EXCEPTION 'COMMS_EMAIL_ALREADY_ADMITTED' USING ERRCODE='55000';\n        END IF;\n      END IF;\n    END LOOP;\n  END IF;\n  IF NEW.status IS NULL OR NEW.status NOT IN ('approved', 'sent') THEN\n    RETURN NEW;\n  END IF;\n  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN\n    RETURN NEW;\n  END IF;\n\n  _raw := btrim(NEW.metadata->>'action_id');\n  IF _raw IS NOT NULL THEN BEGIN _ids := _ids || _raw::uuid; EXCEPTION WHEN invalid_text_representation THEN NULL; END; END IF;\n  IF TG_OP = 'UPDATE' THEN\n    _raw := btrim(OLD.metadata->>'action_id');\n    -- Any text Postgres casts to a uuid ({…}, no dashes, upper case) names the action, exactly as\n    -- trg_ppa_sync_action reads it (round-5 verifier); only text that is not a uuid is ignored.\n    IF _raw IS NOT NULL THEN BEGIN _ids := _ids || _raw::uuid; EXCEPTION WHEN invalid_text_representation THEN NULL; END; END IF;\n  END IF;\n\n  SELECT array_agg(DISTINCT a.action_kind ORDER BY a.action_kind) INTO _kinds\n    FROM public.paige_actions a\n    JOIN public.paige_action_kinds k ON k.slug = a.action_kind\n   WHERE k.executor = 'send_via_approval'\n     AND (a.id = ANY (_ids) OR a.approval_id = NEW.id);\n  IF _kinds IS NULL THEN\n    RETURN NEW;  -- not an outbound-message approval: every other approval is untouched (§58)\n  END IF;\n\n  -- Any send kind without a governed record path is decline/archive only — no proof is consulted.\n  IF cardinality(_kinds)<>1 OR NOT (_kinds[1]=ANY(ARRAY['owner.lead_followup','client.followup','owner.followup_email','comms-draft-reply'])) THEN\n    RAISE EXCEPTION 'SEND_REQUIRES_GOVERNED_SEND: an outbound message is approved only once the business''s verified email has sent it; it can still be declined'\n      USING ERRCODE = '42501',\n            DETAIL  = 'reason_code=decline_only',\n            HINT    = 'This message can be declined for now; sending it from an approval is not available yet.';\n  END IF;\n\n  -- Every action this approval names (NEW or stored OLD metadata.action_id) must be THIS approval's own\n  -- action (paige_actions.approval_id = NEW.id). Otherwise one reply's send could approve this row while\n  -- metadata.action_id points at ANOTHER reply's action, and the approve→action sync would mark that\n  -- other reply done with no send of its own (round-4 security LOW-1). The only writer that approves a\n  -- reply, _lead_reply_record_send, already requires the same link, and advance_action writes it when\n  -- it files the approval; editing action_id while pending stays possible, approving with it does not.\n  IF EXISTS (SELECT 1 FROM unnest(_ids) AS n(id)\n              WHERE NOT EXISTS (SELECT 1 FROM public.paige_actions a WHERE a.id = n.id AND a.approval_id = NEW.id)) THEN\n    RAISE EXCEPTION 'SEND_REQUIRES_GOVERNED_SEND: an outbound message is approved only once the business''s verified email has sent it; it can still be declined'\n      USING ERRCODE = '42501',\n            DETAIL  = 'reason_code=review_and_send',\n            HINT    = 'This approval names a reply that is not its own; review and send each reply from its own approval.';\n  END IF;\n\n  _gs  := NEW.metadata->'governed_send';\n  _mid := CASE WHEN jsonb_typeof(_gs) = 'object' THEN lower(btrim(_gs->>'message_id')) END;\n  _op  := CASE WHEN jsonb_typeof(_gs) = 'object' THEN lower(btrim(_gs->>'operation_id')) END;\n\n  IF _mid ~ _uuid AND _op ~ _uuid THEN\n    SELECT * INTO _msg FROM public.messages WHERE id = _mid::uuid;\n  END IF;\n\n  IF _kinds[1]='comms-draft-reply' AND NOT coalesce(\n    _msg.channel_type='email' AND _msg.direction='outbound' AND _msg.meta->>'source'='comms-draft-reply'\n    AND _msg.meta#>>'{comms_email_binding,governance,draft_source,message_id}'=_msg.id::text\n    AND EXISTS(SELECT 1 FROM public.paige_actions a WHERE a.id=_msg.action_id AND a.approval_id=NEW.id\n      AND a.tenant_id=NEW.tenant_id AND a.contact_id=_msg.contact_id AND a.action_kind='comms-draft-reply'\n      AND coalesce(a.payload->>'channel_type','email')='email'),false) THEN\n    RAISE EXCEPTION 'COMMS_EMAIL_ORIGIN_BINDING_CHANGED' USING ERRCODE='42501';\n  END IF;\n  _tenant := NEW.tenant_id;\n  BEGIN _origin:=(_msg.meta#>>'{comms_email_binding,origin_action_id}')::uuid;\n  EXCEPTION WHEN invalid_text_representation THEN _origin:=NULL; END;\n  -- Existing accepted legacy lead receipts retain their original strict recording contract.\n  -- A newly supported kind, or a sealed lead, must prove its native exact original action.\n  IF (_kinds[1]<>'owner.lead_followup' OR _msg.meta#>>'{comms_email_binding,origin_action_id}' IS NOT NULL)\n   AND (_origin IS NULL OR NOT (_origin=ANY(_ids))\n    OR (SELECT count(*) FROM public.paige_actions a WHERE a.approval_id=NEW.id)<>1\n    OR NOT EXISTS (SELECT 1 FROM public.paige_actions a WHERE a.id=_origin AND a.approval_id=NEW.id\n      AND a.tenant_id=NEW.tenant_id AND a.contact_id=_msg.contact_id AND a.action_kind=_kinds[1]\n      AND a.action_kind=_msg.meta#>>'{comms_email_binding,origin_action_kind}')) THEN\n    RAISE EXCEPTION 'COMMS_EMAIL_ORIGIN_BINDING_CHANGED' USING ERRCODE='42501';\n  END IF;\n\n  IF _msg.id IS NULL\n     OR NOT (_msg.meta ? 'comms_email_binding')\n     OR lower(btrim(_msg.meta#>>'{comms_email_binding,approval_id}')) IS DISTINCT FROM NEW.id::text\n     OR _msg.meta#>>'{comms_email_binding,state}' IS DISTINCT FROM 'provider_accepted'\n     OR lower(_msg.meta#>>'{comms_email_binding,operation_id}') IS DISTINCT FROM _op\n     OR _tenant IS NULL OR _msg.tenant_id IS DISTINCT FROM _tenant\n     OR _msg.contact_id IS NULL\n     OR (_msg.created_at < NEW.created_at AND _kinds[1]<>'comms-draft-reply')\n     OR EXISTS (\n          SELECT 1\n            FROM public.paige_actions a\n            JOIN public.paige_action_kinds k ON k.slug = a.action_kind\n           WHERE k.executor = 'send_via_approval'\n             AND (a.id = ANY (_ids) OR a.approval_id = NEW.id)\n             AND (a.tenant_id IS DISTINCT FROM _msg.tenant_id OR a.contact_id IS DISTINCT FROM _msg.contact_id))\n     OR EXISTS (\n          SELECT 1 FROM public.paige_pending_approvals o\n           WHERE o.id <> NEW.id\n             AND o.status IN ('approved', 'sent')\n             AND lower(o.metadata#>>'{governed_send,message_id}') = _msg.id::text)\n  THEN\n    RAISE EXCEPTION 'SEND_REQUIRES_GOVERNED_SEND: an outbound message is approved only once the business''s verified email has sent it; it can still be declined'\n      USING ERRCODE = '42501',\n            DETAIL  = 'reason_code=review_and_send',\n            HINT    = 'Review and send it from the reply screen; the send is recorded on the approval once the business''s verified email has sent it.';\n  END IF;\n\n  RETURN NEW;\nEND;\n$function$\n","before_md5":"e137d771a63f2fbc6beff88fea2e3d37"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"7e93cb7be01f5bbe37ae3e70d94aac5d","settings":["search_path=pg_catalog, public"],"signature":"prepare_comms_email_send(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,text,jsonb,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.prepare_comms_email_send(_actor_user_id uuid, _expected_tenant_id uuid, _operation_id uuid, _contact_id uuid, _recipient text, _connector_id uuid, _from_address text, _subject text, _body_text text, _body_html text, _content_digest text, _command jsonb, _governance jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE m public.messages%ROWTYPE; c public.channel_connectors%ROWTYPE; b jsonb;\n _uuid constant text:='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';\n _approval text; ap public.paige_pending_approvals%ROWTYPE; _act public.paige_actions%ROWTYPE;\n _live text; _cited text; _constraint text; _action_id uuid;\n agreement_source jsonb;\n _draft_source jsonb; _source_message public.messages%ROWTYPE;\n _source_connector public.channel_connectors%ROWTYPE; _source_version timestamptz;\nBEGIN\n PERFORM public._comms_email_actor(_actor_user_id,_expected_tenant_id);\n PERFORM public._comms_email_governance(_actor_user_id,_expected_tenant_id,_governance);\n IF _operation_id IS NULL THEN RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023'; END IF;\n _draft_source:=_governance->'draft_source';\n IF _draft_source IS NOT NULL THEN\n  IF jsonb_typeof(_draft_source) IS DISTINCT FROM 'object'\n   OR NOT (_draft_source ?& ARRAY['message_id','updated_at'])\n   OR (SELECT count(*) FROM jsonb_object_keys(_draft_source))<>2\n   OR jsonb_typeof(_draft_source->'message_id') IS DISTINCT FROM 'string'\n   OR jsonb_typeof(_draft_source->'updated_at') IS DISTINCT FROM 'string'\n   OR coalesce(_draft_source->>'message_id','') !~ _uuid\n   OR coalesce(_draft_source->>'updated_at','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'\n  THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_INVALID' USING ERRCODE='22023'; END IF;\n  BEGIN _source_version:=(_draft_source->>'updated_at')::timestamptz;\n  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_INVALID' USING ERRCODE='22023';\n  END;\n END IF;\n -- (6) The drafted reply this send answers, from the door's server-built governance record. NULL = none.\n _approval:=nullif(lower(btrim(_governance->>'approval_id')),'');\n IF _approval IS NOT NULL AND _approval !~ _uuid THEN RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023'; END IF;\n PERFORM pg_advisory_xact_lock(hashtextextended(_operation_id::text,32847));\n\n SELECT * INTO m FROM public.messages WHERE meta#>>'{comms_email_binding,operation_id}'=_operation_id::text;\n IF FOUND THEN\n  b:=m.meta->'comms_email_binding';\n  IF m.tenant_id IS DISTINCT FROM _expected_tenant_id OR b->>'actor_user_id' IS DISTINCT FROM _actor_user_id::text\n   OR b->'command' IS DISTINCT FROM _command OR b->>'content_digest' IS DISTINCT FROM _content_digest\n   OR lower(b->>'approval_id') IS DISTINCT FROM _approval\n   OR b#>'{governance,draft_source}' IS DISTINCT FROM _draft_source THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_REPLAY_MISMATCH' USING ERRCODE='22023';\n  END IF;\n  IF _governance->>'purpose'='agreement_signature_request'\n   AND b->'governance' IS DISTINCT FROM _governance THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_REPLAY_MISMATCH' USING ERRCODE='22023'; END IF;\n  RETURN jsonb_build_object('ok',true,'replayed',true,'state',b->>'state','message_id',m.id);\n END IF;\n\n -- Lock the original saved row, never INSERT a substitute or relabel a commercial binding.\n IF _draft_source IS NOT NULL THEN\n  IF _governance->>'purpose'='agreement_signature_request' THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501'; END IF;\n  SELECT * INTO _source_message FROM public.messages\n   WHERE id=(_draft_source->>'message_id')::uuid AND tenant_id=_expected_tenant_id FOR UPDATE;\n  IF _source_message.id IS NULL OR _source_message.channel_type IS DISTINCT FROM 'email'\n   OR _source_message.direction IS DISTINCT FROM 'outbound' OR _source_message.status IS DISTINCT FROM 'draft'\n   OR _source_message.contact_id IS DISTINCT FROM _contact_id OR _source_message.provider_message_id IS NOT NULL\n   OR _source_message.meta ?| ARRAY['comms_email_binding','sales_invoice_binding','growth_sequence_binding','email_campaign_binding']\n  THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n  IF _source_message.updated_at IS DISTINCT FROM _source_version THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;\n  -- Changing From must not turn another person's personal source into a shared draft.\n  SELECT * INTO _source_connector FROM public.channel_connectors\n   WHERE id=_source_message.connector_id AND tenant_id=_expected_tenant_id FOR SHARE;\n  IF _source_connector.id IS NULL OR _source_connector.active IS DISTINCT FROM true\n   OR _source_connector.status IS DISTINCT FROM 'active' OR _source_connector.channel_type IS DISTINCT FROM 'email'\n   OR NOT coalesce(_source_connector.mailbox_class='shared_support'\n    OR (_source_connector.mailbox_class='personal' AND _source_connector.mailbox_owner_user_id=_actor_user_id),false)\n  THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n  IF _source_connector.mailbox_class='personal'\n   AND _connector_id IS DISTINCT FROM _source_message.connector_id THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501';\n  END IF;\n END IF;\n\n -- ORIGINAL agreement lock precedes its child message, including distinct\n -- transport intents. A lost acknowledgement is inspected, never a new send.\n IF _governance->>'purpose'='agreement_signature_request' THEN\n  agreement_source:=private.e04_agreement_email_origin(_actor_user_id,_expected_tenant_id,_governance,true);\n  IF _operation_id::text IS DISTINCT FROM agreement_source->>'operation_id'\n   OR _contact_id::text IS DISTINCT FROM agreement_source->>'client_id'\n   OR _recipient IS DISTINCT FROM agreement_source#>>'{message,to}'\n   OR _subject IS DISTINCT FROM agreement_source#>>'{message,subject}'\n   OR _body_text IS DISTINCT FROM agreement_source#>>'{message,body_text}'\n   OR _body_html IS DISTINCT FROM agreement_source#>>'{message,body_html}'\n   OR _connector_id::text IS DISTINCT FROM agreement_source#>>'{sender,connector_id}'\n   OR _from_address IS DISTINCT FROM agreement_source#>>'{sender,from_address}'\n   OR _command IS DISTINCT FROM agreement_source->'command' THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_AGREEMENT_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;\n  IF EXISTS(SELECT 1 FROM public.messages previous\n    WHERE previous.tenant_id=_expected_tenant_id\n     AND previous.meta#>>'{comms_email_binding,governance,purpose}'='agreement_signature_request'\n     AND previous.meta#>>'{comms_email_binding,governance,agreement_work_id}'=agreement_source->>'work_id'\n     AND previous.meta#>>'{comms_email_binding,governance,signer_id}'=agreement_source#>>'{signer,id}') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_AGREEMENT_INTENT_ALREADY_RECORDED' USING ERRCODE='55000'; END IF;\n ELSE\n -- The command is the canonical approved shape; its fields must be the ones being prepared.\n IF _command IS NULL OR jsonb_typeof(_command)<>'object' OR _command->>'action' IS DISTINCT FROM 'comms.email_send'\n  OR _command->>'contact_id' IS DISTINCT FROM _contact_id::text OR _command->>'subject' IS DISTINCT FROM _subject\n  OR _command->>'body' IS DISTINCT FROM _body_text\n  OR (_command->>'connector_id' IS NOT NULL AND _command->>'connector_id' IS DISTINCT FROM _connector_id::text) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023';\n END IF;\n\n END IF;\n\n -- (6) One live send per reply approval. The approval row is locked, so two confirms of different\n -- operations for the same reply serialize here; the second sees the first's send and is refused.\n IF _approval IS NOT NULL THEN\n  SELECT * INTO ap FROM public.paige_pending_approvals WHERE id=_approval::uuid FOR UPDATE;\n  BEGIN _action_id:=nullif(btrim(ap.metadata->>'action_id'),'')::uuid;\n  EXCEPTION WHEN invalid_text_representation THEN _action_id:=NULL; END;\n  -- PPA -> exact canonical action. Lock every backlink deterministically before proving uniqueness.\n  PERFORM 1 FROM public.paige_actions a WHERE a.approval_id=ap.id ORDER BY a.id FOR UPDATE;\n  IF ap.id IS NOT NULL AND _action_id IS NOT NULL THEN\n   SELECT * INTO _act FROM public.paige_actions a\n    WHERE a.id=_action_id AND a.approval_id=ap.id AND a.tenant_id=ap.tenant_id;\n  END IF;\n  IF ap.id IS NULL OR ap.tenant_id IS DISTINCT FROM _expected_tenant_id\n   OR _act.id IS NULL OR (_act.action_kind NOT IN ('owner.lead_followup','client.followup','owner.followup_email') AND NOT coalesce(_act.action_kind='comms-draft-reply' AND _draft_source IS NOT NULL\n    AND _source_message.id::text=_draft_source->>'message_id' AND _source_message.action_id=_act.id\n    AND _source_message.meta->>'source'='comms-draft-reply'\n    AND coalesce(_act.payload->>'channel_type','email')='email',false)) OR _act.contact_id IS DISTINCT FROM _contact_id\n   OR (ap.contact_id IS NOT NULL AND ap.contact_id IS DISTINCT FROM _contact_id)\n   OR (SELECT count(*) FROM public.paige_actions a WHERE a.approval_id=ap.id)<>1\n   OR NOT EXISTS (SELECT 1 FROM public.paige_action_kinds k WHERE k.slug=_act.action_kind AND k.executor='send_via_approval') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_INVALID' USING ERRCODE='42501';\n  END IF;\n  IF ap.status IN ('approved','sent') THEN RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_ALREADY_SENT' USING ERRCODE='55000'; END IF;\n  IF ap.status IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_NOT_PENDING' USING ERRCODE='55000'; END IF;\n  IF _act.status IS NULL OR _act.status NOT IN ('drafted','pending_approval') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_ORIGIN_NOT_SENDABLE' USING ERRCODE='55000';\n  END IF;\n  -- A send prepared for this approval that has not failed or been refused …\n  SELECT o.meta#>>'{comms_email_binding,state}' INTO _live FROM public.messages o\n   WHERE o.meta ? 'comms_email_binding' AND lower(o.meta#>>'{comms_email_binding,approval_id}')=_approval\n     AND coalesce(o.meta#>>'{comms_email_binding,state}','') NOT IN ('failed','refused')\n   ORDER BY (o.meta#>>'{comms_email_binding,state}'='provider_accepted') DESC LIMIT 1;\n  -- … or the send the approval itself cites (metadata.governed_send), whatever it was prepared for.\n  IF _live IS NULL THEN\n   _cited:=lower(btrim(ap.metadata#>>'{governed_send,operation_id}'));\n   IF _cited ~ _uuid THEN\n    SELECT o.meta#>>'{comms_email_binding,state}' INTO _live FROM public.messages o\n     WHERE o.meta ? 'comms_email_binding' AND o.meta#>>'{comms_email_binding,operation_id}'=_cited\n       AND o.tenant_id=_expected_tenant_id AND coalesce(o.meta#>>'{comms_email_binding,state}','') NOT IN ('failed','refused');\n   END IF;\n  END IF;\n  IF _live='provider_accepted' THEN RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_ALREADY_SENT' USING ERRCODE='55000'; END IF;\n  IF _live IS NOT NULL THEN RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_SEND_IN_PROGRESS' USING ERRCODE='55000'; END IF;\n END IF;\n\n\n -- A saved action-owned draft must use its ORIGINAL already-validated reply approval.\n IF _draft_source IS NOT NULL AND _source_message.action_id IS DISTINCT FROM _act.id THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501'; END IF;\n PERFORM 1 FROM public.clients WHERE id=_contact_id AND tenant_id=_expected_tenant_id FOR SHARE;\n IF NOT FOUND THEN RAISE EXCEPTION 'COMMS_EMAIL_CONTACT_NOT_IN_WORKSPACE' USING ERRCODE='42501'; END IF;\n -- An approved business/witness signer belongs to the original agreement;\n -- it is not manufactured as another client contact method.\n IF agreement_source IS NULL THEN\n IF _recipient IS NULL OR _recipient IS DISTINCT FROM lower(btrim(_recipient)) OR length(_recipient)>320\n  OR NOT EXISTS (SELECT 1 FROM public.client_contact_methods cm WHERE cm.tenant_id=_expected_tenant_id AND cm.client_id=_contact_id\n   AND cm.kind='email' AND lower(btrim(cm.value))=_recipient) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_RECIPIENT_CHANGED' USING ERRCODE='40001';\n END IF;\n\n END IF;\n\n SELECT * INTO c FROM public.channel_connectors WHERE id=_connector_id AND tenant_id=_expected_tenant_id FOR SHARE;\n IF c.id IS NULL OR c.active IS DISTINCT FROM true OR c.status IS DISTINCT FROM 'active' OR c.channel_type IS DISTINCT FROM 'email'\n  OR c.provider IS NULL OR c.provider NOT IN ('resend','gmail','smtp','sendgrid') OR coalesce(length(btrim(c.from_address)),0)=0\n  OR _from_address IS NULL OR lower(btrim(c.from_address)) IS DISTINCT FROM lower(btrim(_from_address))\n  OR NOT coalesce(c.mailbox_class='shared_support'\n    OR (c.mailbox_class='personal' AND c.mailbox_owner_user_id=_actor_user_id),false) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_SENDER_CHANGED' USING ERRCODE='40001';\n END IF;\n -- PAIGE Email (SendGrid): a connector row alone is never proof of sender identity (a workspace\n -- admin can write one). The From's domain must carry SendGrid verification facts that only the\n -- verification service can write (guard_tenant_email_domain_sendgrid_facts, 20271031000100).\n IF c.provider='sendgrid' AND NOT public._comms_email_sendgrid_sender_verified(_expected_tenant_id,c.from_address) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_SENDER_UNVERIFIED' USING ERRCODE='42501';\n END IF;\n\n IF _subject IS NULL OR length(btrim(_subject))=0 OR length(_subject)>200 OR _subject ~ E'[\\r\\n]'\n  OR _body_text IS NULL OR length(btrim(_body_text))=0 OR length(_body_text)>10000\n  OR _body_html IS NULL OR length(_body_html)=0 OR length(_body_html)>100000 THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023';\n END IF;\n IF _content_digest IS DISTINCT FROM encode(extensions.digest(convert_to(_recipient||E'\\n'||_connector_id::text||E'\\n'||_subject||E'\\n'||_body_text,'UTF8'),'sha256'),'hex') THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DIGEST_MISMATCH' USING ERRCODE='22023';\n END IF;\n\n\n -- An earlier identical send whose outcome is not known must be reconciled, never re-sent.\n IF EXISTS (SELECT 1 FROM public.messages o WHERE o.tenant_id=_expected_tenant_id AND o.meta ? 'comms_email_binding'\n   AND o.meta#>>'{comms_email_binding,recipient}'=_recipient AND o.meta#>>'{comms_email_binding,content_digest}'=_content_digest\n   AND o.meta#>>'{comms_email_binding,state}' IN ('dispatching','unknown')) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_RECONCILIATION_REQUIRED' USING ERRCODE='55000';\n END IF;\n\n b:=jsonb_build_object('operation_id',_operation_id::text,'tenant_id',_expected_tenant_id,'actor_user_id',_actor_user_id,\n  'contact_id',_contact_id,'recipient',_recipient,'connector_id',_connector_id,'from_address',lower(btrim(c.from_address)),\n  'provider',c.provider,'subject',_subject,'body_text',_body_text,'body_html',_body_html,'content_digest',_content_digest,\n  'command',_command,'governance',_governance,'state','prepared','attempts',0,'prepared_at',now(),'claimed_at',NULL,\n  'finalized_at',NULL,'provider_message_id',NULL,'outcome_reason',NULL,'approval_id',_approval,'origin_action_id',_act.id,'origin_action_kind',_act.action_kind);\n BEGIN\n  IF _draft_source IS NOT NULL THEN\n   UPDATE public.messages SET connector_id=_connector_id,\n    recipients=CASE WHEN _source_message.recipients->0->>'address'=_recipient AND jsonb_array_length(_source_message.recipients)=1\n      THEN _source_message.recipients ELSE jsonb_build_array(jsonb_build_object('address',_recipient)) END,\n    sender=CASE WHEN _source_message.sender->>'address'=lower(btrim(c.from_address))\n      THEN _source_message.sender ELSE jsonb_build_object('address',lower(btrim(c.from_address))) END,\n    subject=_subject,body_text=_body_text,body_html=_body_html,attachments='[]'::jsonb,\n    meta=coalesce(_source_message.meta,'{}'::jsonb)||jsonb_build_object('comms_email_binding',b)\n    WHERE id=_source_message.id AND tenant_id=_expected_tenant_id RETURNING * INTO m;\n   IF NOT FOUND THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;\n  ELSE\n  INSERT INTO public.messages(tenant_id,contact_id,connector_id,thread_key,channel_type,direction,status,recipients,sender,subject,body_text,body_html,meta)\n  VALUES(_expected_tenant_id,_contact_id,_connector_id,'contact:'||_expected_tenant_id::text||':'||_contact_id::text,'email','outbound','draft',\n   jsonb_build_array(jsonb_build_object('address',_recipient)),jsonb_build_object('address',lower(btrim(c.from_address))),\n   _subject,_body_text,_body_html,jsonb_build_object('source','comms-email-command','comms_email_binding',b))\n  RETURNING * INTO m;\n  END IF;\n EXCEPTION WHEN unique_violation THEN\n  GET STACKED DIAGNOSTICS _constraint = CONSTRAINT_NAME;\n  IF _constraint='messages_comms_email_approval_live' THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_APPROVAL_SEND_IN_PROGRESS' USING ERRCODE='55000';\n  END IF;\n  RAISE;\n END;\n RETURN jsonb_build_object('ok',true,'replayed',false,'state','prepared','message_id',m.id);\nEND $function$\n","before_md5":"44040e47f20c4a285177b09ea9f5a717"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"910674fc5c623564b46b4bb8f0f9258d","settings":["search_path=pg_catalog, public"],"signature":"prepare_comms_email_send(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,text,jsonb,jsonb,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.prepare_comms_email_send(_actor_user_id uuid, _expected_tenant_id uuid, _operation_id uuid, _contact_id uuid, _recipient text, _connector_id uuid, _from_address text, _subject text, _body_text text, _body_html text, _content_digest text, _command jsonb, _governance jsonb, _send_at timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE m public.messages%ROWTYPE; r jsonb; send_at_text text;\nBEGIN\n PERFORM public._comms_email_actor(_actor_user_id,_expected_tenant_id);\n -- A whole minute, at least 30 s ahead (the door asks for 2 min when the card is raised and refuses\n -- under 60 s at confirm), at most 30 days (+10 min: a card raised at the limit may be confirmed later).\n IF _send_at IS NULL OR _send_at IS DISTINCT FROM (date_trunc('minute',_send_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC')\n  OR _send_at<now()+interval '30 seconds' OR _send_at>now()+interval '30 days 10 minutes' THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_SEND_AT_INVALID' USING ERRCODE='22023';\n END IF;\n -- A drafted lead reply (one send per approval, recorded when accepted) and an agreement's signing\n -- request are answered now; neither is scheduled.\n IF _governance->>'purpose' IS NOT DISTINCT FROM 'agreement_signature_request' OR (coalesce(btrim(_governance->>'approval_id'),'')<>'' AND NOT (_governance ? 'draft_source')) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_SCHEDULE_NOT_SUPPORTED' USING ERRCODE='22023';\n END IF;\n IF _operation_id IS NULL THEN RAISE EXCEPTION 'COMMS_EMAIL_CONTENT_INVALID' USING ERRCODE='22023'; END IF;\n send_at_text:=to_char(_send_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"');\n -- The 13-argument body's own lock (re-entrant here): the replay read below and its insert serialize.\n PERFORM pg_advisory_xact_lock(hashtextextended(_operation_id::text,32847));\n SELECT * INTO m FROM public.messages WHERE meta#>>'{comms_email_binding,operation_id}'=_operation_id::text;\n IF FOUND AND m.meta#>>'{comms_email_binding,send_at}' IS DISTINCT FROM send_at_text THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_REPLAY_MISMATCH' USING ERRCODE='22023';\n END IF;\n r:=public.prepare_comms_email_send(_actor_user_id,_expected_tenant_id,_operation_id,_contact_id,_recipient,_connector_id,\n   _from_address,_subject,_body_text,_body_html,_content_digest,_command,_governance);\n IF r->'replayed' IS DISTINCT FROM 'true'::jsonb THEN\n  UPDATE public.messages SET status='queued',scheduled_for=_send_at,\n    meta=jsonb_set(meta,'{comms_email_binding,send_at}',to_jsonb(send_at_text))\n   WHERE id=(r->>'message_id')::uuid AND status='draft'\n    AND meta#>>'{comms_email_binding,operation_id}'=_operation_id::text AND meta#>>'{comms_email_binding,state}'='prepared';\n  IF NOT FOUND THEN RAISE EXCEPTION 'COMMS_EMAIL_SCHEDULE_UNAVAILABLE' USING ERRCODE='55000'; END IF;\n END IF;\n RETURN r||jsonb_build_object('send_at',send_at_text);\nEND $function$\n","before_md5":"3e228c9e0298724b6f3b6de2eca892ca"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"1b3d7bf95f82d6cfddcb635ff61b3f2b","settings":["search_path=pg_catalog, public"],"signature":"prepare_comms_email_send(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,text,jsonb,jsonb,timestamp with time zone,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.prepare_comms_email_send(_actor_user_id uuid, _expected_tenant_id uuid, _operation_id uuid, _contact_id uuid, _recipient text, _connector_id uuid, _from_address text, _subject text, _body_text text, _body_html text, _content_digest text, _command jsonb, _governance jsonb, _send_at timestamp with time zone, _attachments jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE m public.messages%ROWTYPE; r jsonb; b jsonb; send_at_text text;\nBEGIN\n PERFORM public._comms_email_actor(_actor_user_id,_expected_tenant_id);\n IF _attachments IS NULL OR jsonb_typeof(_attachments)<>'array' OR jsonb_array_length(_attachments)=0 THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_INVALID' USING ERRCODE='22023';\n END IF;\n -- A drafted lead reply is sent exactly as drafted and recorded against its approval; an agreement's\n -- signing request is its own message. Neither carries files through this door.\n IF _governance->>'purpose' IS NOT DISTINCT FROM 'agreement_signature_request' OR (coalesce(btrim(_governance->>'approval_id'),'')<>'' AND NOT (_governance ? 'draft_source')) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_NOT_SUPPORTED' USING ERRCODE='22023';\n END IF;\n IF _operation_id IS NULL OR NOT public._comms_email_attachment_manifest_ok(_expected_tenant_id,_operation_id,_attachments) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_INVALID' USING ERRCODE='22023';\n END IF;\n IF _send_at IS NOT NULL THEN send_at_text:=to_char(_send_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'); END IF;\n -- The 13-argument body's own lock (re-entrant): this replay read, its insert and the update below serialize.\n PERFORM pg_advisory_xact_lock(hashtextextended(_operation_id::text,32847));\n SELECT * INTO m FROM public.messages WHERE meta#>>'{comms_email_binding,operation_id}'=_operation_id::text;\n IF FOUND AND (m.meta#>'{comms_email_binding,attachments}' IS DISTINCT FROM _attachments\n   OR m.meta#>>'{comms_email_binding,send_at}' IS DISTINCT FROM send_at_text) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_REPLAY_MISMATCH' USING ERRCODE='22023';\n END IF;\n IF _send_at IS NULL THEN\n  r:=public.prepare_comms_email_send(_actor_user_id,_expected_tenant_id,_operation_id,_contact_id,_recipient,_connector_id,\n    _from_address,_subject,_body_text,_body_html,_content_digest,_command,_governance);\n ELSE\n  r:=public.prepare_comms_email_send(_actor_user_id,_expected_tenant_id,_operation_id,_contact_id,_recipient,_connector_id,\n    _from_address,_subject,_body_text,_body_html,_content_digest,_command,_governance,_send_at);\n END IF;\n IF r->'replayed' IS DISTINCT FROM 'true'::jsonb THEN\n  SELECT * INTO m FROM public.messages WHERE id=(r->>'message_id')::uuid FOR UPDATE;\n  b:=m.meta->'comms_email_binding';\n  -- Only the SendGrid arm sends governed files. Raising here rolls back the row just inserted.\n  IF b->>'provider' IS NULL OR b->>'provider' NOT IN ('sendgrid','resend') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_PROVIDER_UNSUPPORTED' USING ERRCODE='22023';\n  END IF;\n  UPDATE public.messages SET\n    meta=jsonb_set(meta,'{comms_email_binding,attachments}',_attachments),\n    attachments=(SELECT jsonb_agg(jsonb_build_object('url',e->>'path','name',e->>'name','mime',e->>'mime','size',(e->>'size')::bigint) ORDER BY ordinality)\n                 FROM jsonb_array_elements(_attachments) WITH ORDINALITY AS a(e,ordinality))\n   WHERE id=m.id AND meta#>>'{comms_email_binding,operation_id}'=_operation_id::text AND meta#>>'{comms_email_binding,state}'='prepared';\n  IF NOT FOUND THEN RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_UNAVAILABLE' USING ERRCODE='55000'; END IF;\n END IF;\n RETURN r||jsonb_build_object('attachments',jsonb_array_length(_attachments));\nEND $function$\n","before_md5":"9dd86fac153138c0639d969dbecd6bad"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"348fe822a186b8b41c8fa0ae08ccbb69","settings":["search_path=pg_catalog, public"],"signature":"prepare_comms_email_send(uuid,uuid,uuid,uuid,text,uuid,text,text,text,text,text,jsonb,jsonb,timestamp with time zone,jsonb,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.prepare_comms_email_send(_actor_user_id uuid, _expected_tenant_id uuid, _operation_id uuid, _contact_id uuid, _recipient text, _connector_id uuid, _from_address text, _subject text, _body_text text, _body_html text, _content_digest text, _command jsonb, _governance jsonb, _send_at timestamp with time zone, _attachments jsonb, _draft_source jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE governed jsonb;\nBEGIN\n IF _draft_source IS NULL OR jsonb_typeof(_draft_source) IS DISTINCT FROM 'object' THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_INVALID' USING ERRCODE='22023'; END IF;\n IF _governance ? 'draft_source' AND _governance->'draft_source' IS DISTINCT FROM _draft_source THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_INVALID' USING ERRCODE='22023'; END IF;\n governed:=_governance||jsonb_build_object('draft_source',_draft_source);\n IF _attachments IS NOT NULL THEN\n  RETURN public.prepare_comms_email_send(_actor_user_id,_expected_tenant_id,_operation_id,_contact_id,_recipient,_connector_id,_from_address,_subject,_body_text,_body_html,_content_digest,_command,governed,_send_at,_attachments);\n ELSIF _send_at IS NOT NULL THEN\n  RETURN public.prepare_comms_email_send(_actor_user_id,_expected_tenant_id,_operation_id,_contact_id,_recipient,_connector_id,_from_address,_subject,_body_text,_body_html,_content_digest,_command,governed,_send_at);\n ELSE\n  RETURN public.prepare_comms_email_send(_actor_user_id,_expected_tenant_id,_operation_id,_contact_id,_recipient,_connector_id,_from_address,_subject,_body_text,_body_html,_content_digest,_command,governed);\n END IF;\nEND\n$function$\n","before_md5":null},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"03302395a40ba59e43d2012538d2cea0","settings":["search_path=pg_catalog, public"],"signature":"read_comms_email_send_binding(uuid)","definition":"CREATE OR REPLACE FUNCTION public.read_comms_email_send_binding(_message_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE m public.messages%ROWTYPE; c public.channel_connectors%ROWTYPE; b jsonb;\n ap public.paige_pending_approvals%ROWTYPE; a public.paige_actions%ROWTYPE;\n approval uuid; origin uuid; named uuid; origin_ok boolean:=true;\n agreement_source jsonb;\nBEGIN\n SELECT * INTO m FROM public.messages WHERE id=_message_id;\n b:=m.meta->'comms_email_binding'; IF b IS NULL THEN RETURN NULL; END IF;\n PERFORM public._comms_email_release_actor(b,m.tenant_id);\n -- Source is resolved BEFORE the message lock; claim takes the same parent\n -- first. Terminal history is never fresh permission or a re-send.\n IF b#>>'{governance,purpose}'='agreement_signature_request' THEN\n  agreement_source:=private.e04_agreement_email_binding(b,b->>'state' IN ('prepared','dispatching'));\n END IF;\n -- Only a fresh prepared admission needs pending-origin eligibility. Original admitted outcomes\n -- and the incumbent bounded same-operation reconciliation do not acquire fresh approval authority.\n IF b->>'approval_id' IS NOT NULL AND b->>'state'='prepared' THEN\n  BEGIN approval:=(b->>'approval_id')::uuid; origin:=(b->>'origin_action_id')::uuid;\n  EXCEPTION WHEN invalid_text_representation THEN approval:=NULL; origin:=NULL; END;\n  SELECT * INTO ap FROM public.paige_pending_approvals WHERE id=approval FOR UPDATE;\n  SELECT * INTO a FROM public.paige_actions WHERE id=origin FOR UPDATE;\n  BEGIN named:=nullif(btrim(ap.metadata->>'action_id'),'')::uuid;\n  EXCEPTION WHEN invalid_text_representation THEN named:=NULL; END;\n  origin_ok:=coalesce(ap.id IS NOT NULL AND origin IS NOT NULL AND a.id=origin AND named=origin\n   AND ap.tenant_id=m.tenant_id AND a.tenant_id=m.tenant_id AND a.approval_id=ap.id\n   AND a.contact_id=m.contact_id AND (ap.contact_id IS NULL OR ap.contact_id=m.contact_id)\n   AND ap.status='pending' AND a.status IN ('drafted','pending_approval')\n   AND (a.action_kind IN ('owner.lead_followup','client.followup','owner.followup_email') OR coalesce(a.action_kind='comms-draft-reply' AND coalesce(a.payload->>'channel_type','email')='email'\n    AND m.action_id=a.id AND m.channel_type='email' AND m.meta->>'source'='comms-draft-reply'\n    AND b#>>'{governance,draft_source,message_id}'=m.id::text,false))\n   AND a.action_kind=b->>'origin_action_kind'\n   AND EXISTS (SELECT 1 FROM public.paige_action_kinds k WHERE k.slug=a.action_kind AND k.executor='send_via_approval')\n   AND (SELECT count(*) FROM public.paige_actions x WHERE x.approval_id=ap.id)=1,false);\n END IF;\n -- Re-read after any origin-lock wait; a concurrent winning claim may have advanced state.\n SELECT * INTO m FROM public.messages WHERE id=_message_id FOR UPDATE;\n IF ((m.meta->'comms_email_binding')-ARRAY['state','attempts','claimed_at','finalized_at','provider_message_id','outcome_reason'])\n  IS DISTINCT FROM (b-ARRAY['state','attempts','claimed_at','finalized_at','provider_message_id','outcome_reason']) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_BINDING_CHANGED' USING ERRCODE='40001';\n END IF;\n b:=m.meta->'comms_email_binding';\n IF b->>'state'='prepared' AND a.action_kind='comms-draft-reply' AND NOT coalesce(a.action_kind='comms-draft-reply' AND coalesce(a.payload->>'channel_type','email')='email'\n    AND m.action_id=a.id AND m.channel_type='email' AND m.meta->>'source'='comms-draft-reply'\n    AND b#>>'{governance,draft_source,message_id}'=m.id::text,false) THEN origin_ok:=false; END IF;\n IF b->>'state' IS DISTINCT FROM 'prepared' THEN origin_ok:=true; END IF;\n SELECT * INTO c FROM public.channel_connectors WHERE id=m.connector_id AND tenant_id=m.tenant_id FOR SHARE;\n -- Recheck the ORIGINAL lease/approval after any connector wait. The parent\n -- agreement lock was acquired above; this adds no inverse message->parent lock.\n IF agreement_source IS NOT NULL THEN\n  agreement_source:=private.e04_agreement_email_binding(b,b->>'state' IN ('prepared','dispatching'));\n END IF;\n RETURN b||jsonb_build_object('message_id',m.id,'tenant_id',m.tenant_id,'channel_type',m.channel_type,'message_status',m.status,\n  'origin_eligible',origin_ok,'eligible',origin_ok AND m.channel_type='email' AND m.direction='outbound'\n   AND m.tenant_id::text=b->>'tenant_id' AND m.contact_id::text=b->>'contact_id' AND m.connector_id::text=b->>'connector_id'\n   AND m.subject IS NOT DISTINCT FROM b->>'subject' AND m.body_html IS NOT DISTINCT FROM b->>'body_html'\n   AND m.recipients->0->>'address' IS NOT DISTINCT FROM b->>'recipient'\n   AND coalesce(c.active=true AND c.status='active' AND c.channel_type='email' AND c.provider=b->>'provider'\n    AND lower(btrim(c.from_address))=b->>'from_address',false)\n   AND coalesce(c.mailbox_class='shared_support'\n     OR (c.mailbox_class='personal' AND c.mailbox_owner_user_id=(b->>'actor_user_id')::uuid),false)\n   AND (b->>'provider' IS DISTINCT FROM 'sendgrid' OR public._comms_email_sendgrid_sender_verified(m.tenant_id,b->>'from_address'))\n   AND (agreement_source IS NOT NULL OR EXISTS (SELECT 1 FROM public.client_contact_methods cm WHERE cm.tenant_id=m.tenant_id AND cm.client_id=m.contact_id\n    AND cm.kind='email' AND lower(btrim(cm.value))=b->>'recipient')))\n  || CASE WHEN agreement_source IS NOT NULL THEN jsonb_build_object('agreement_source',agreement_source) ELSE '{}'::jsonb END;\nEND $function$\n","before_md5":"f34ab7d3e7328f8699b7e9eab4de3081"},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","owner":"postgres","definer":true,"full_md5":"95250e91aa6a5c100fe22a9b11f57678","settings":["search_path=public"],"signature":"read_message_content(uuid)","definition":"CREATE OR REPLACE FUNCTION public.read_message_content(p_message_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_msg record;\n  v_class text;\n  v_owner uuid;\n  v_status text;\n  v_active boolean;\n  v_tenant uuid := public.current_user_tenant_id();\nbegin\n  select m.* into v_msg from public.messages m where m.id = p_message_id;\n  if not found then return null; end if;\n  if v_msg.tenant_id is distinct from v_tenant then return null; end if;\n\n  if v_msg.connector_id is null then\n    -- A row with no connector was never a synced mailbox message; tenant\n    -- authority (checked below) is the gate.\n    v_class := 'shared_support'; v_owner := null; v_status := 'active'; v_active := true;\n  else\n    select cc.mailbox_class, cc.mailbox_owner_user_id, cc.status, cc.active\n      into v_class, v_owner, v_status, v_active\n      from public.channel_connectors cc where cc.id = v_msg.connector_id;\n    if not found then return null; end if;\n  end if;\n\n  -- Revoked or disconnected consent refuses the read, fail-closed.\n  if v_status <> 'active' or v_active is not true then\n    return jsonb_build_object('ok', false, 'code', 'MAILBOX_INACTIVE');\n  end if;\n\n  if v_class = 'personal' then\n    if v_owner is null or v_owner <> auth.uid() then\n      if not public.is_platform_owner() then\n        return jsonb_build_object('ok', false, 'code', 'PERSONAL_MAILBOX_NOT_OWNER');\n      end if;\n    end if;\n  else\n    -- ANT-38: TENANT-scoped authority (owner|admin of THIS tenant), not the\n    -- global admin role. Platform owner preserved.\n    if not public.is_tenant_admin(v_tenant) and not public.is_platform_owner() then\n      return jsonb_build_object('ok', false, 'code', 'WORKSPACE_ROLE_REQUIRED');\n    end if;\n  end if;\n\n  return jsonb_build_object(\n    'ok', true,\n    'id', v_msg.id,\n    'direction', v_msg.direction,\n    'channel', v_msg.channel_type,\n    'mailbox_class', v_class,\n    'subject', v_msg.subject,\n    'status', v_msg.status,\n    'contact_id', v_msg.contact_id,\n    'thread_key', v_msg.thread_key,\n    'sender', v_msg.sender,\n    'body_text', left(v_msg.body_text, 8000),\n    'body_truncated', coalesce(length(v_msg.body_text), 0) > 8000,\n    -- Additive context through this SAME original permission gate. Ordinary\n    -- clipped body fields above remain exact. This is a source read, never approval.\n    'saved_email_draft', case when v_msg.channel_type='email' and v_msg.direction='outbound'\n      and v_msg.status='draft' and v_msg.provider_message_id is null and v_msg.contact_id is not null\n      -- Unknown mailbox provenance is not an editable source. Do not expand\n      -- legacy privileged ordinary reads into another person's complete draft.\n      and v_msg.connector_id is not null\n      and (v_class is distinct from 'personal' or v_owner=auth.uid())\n      and v_msg.updated_at is not null\n      and not (coalesce(v_msg.meta,'{}'::jsonb) ?| array['comms_email_binding','sales_invoice_binding','growth_sequence_binding','email_campaign_binding'])\n      and coalesce(length(v_msg.body_text),0)<=10000 and coalesce(length(v_msg.body_html),0)<=100000\n      then jsonb_build_object('source',jsonb_build_object('message_id',v_msg.id,'updated_at',v_msg.updated_at),\n        'body_text',v_msg.body_text,'body_html',v_msg.body_html) else null end,\n    'labels', coalesce((\n      select jsonb_agg(jsonb_build_object('label', l.label, 'source', l.source) order by l.label)\n      from public.message_labels l where l.message_id = v_msg.id\n    ), '[]'::jsonb),\n    'classification', (\n      select jsonb_build_object('intent', k.intent, 'confidence', k.confidence,\n                                'risk_tier', k.risk_tier, 'summary', k.summary, 'decided_at', k.decided_at)\n      from public.message_classifications k where k.message_id = v_msg.id\n    ),\n    'unsubscribe', v_msg.meta ? 'list_unsubscribe',\n    'sent_at', v_msg.sent_at,\n    'created_at', v_msg.created_at\n  );\nend;\n$function$\n","before_md5":"3940dd0f8d7a9b5ae668707a2513212a"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","definer":true,"full_md5":"cd746abf4bae4849a2a760716b690ded","settings":["search_path=pg_catalog, public"],"signature":"save_comms_email_draft(uuid,uuid,uuid,uuid,timestamp with time zone,uuid,uuid,text,text,text,jsonb,timestamp with time zone,uuid)","definition":"CREATE OR REPLACE FUNCTION public.save_comms_email_draft(_actor uuid, _tenant uuid, _save_id uuid, _message_id uuid, _expected_updated_at timestamp with time zone, _contact uuid, _connector uuid, _subject text, _text text, _html text, _attachments jsonb, _send_at timestamp with time zone, _approval uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE m public.messages%ROWTYPE; source_mailbox public.channel_connectors%ROWTYPE;\n chosen public.channel_connectors%ROWTYPE; ap public.paige_pending_approvals%ROWTYPE;\n act public.paige_actions%ROWTYPE; file jsonb; request_digest text; receipt_id uuid; prior_receipt public.paige_audit_log%ROWTYPE;\nBEGIN\n PERFORM public._comms_email_actor(_actor,_tenant);\n IF _save_id IS NULL OR _message_id IS NULL OR _expected_updated_at IS NULL OR _contact IS NULL OR _connector IS NULL\n  OR _subject IS NULL OR length(_subject) NOT BETWEEN 1 AND 200 OR length(btrim(_subject))=0\n  OR position(chr(10) in _subject)>0 OR position(chr(13) in _subject)>0\n  OR _text IS NULL OR length(_text) NOT BETWEEN 1 AND 10000 OR length(btrim(_text))=0\n  OR _html IS NULL OR length(_html) NOT BETWEEN 1 AND 100000\n  OR _attachments IS NULL OR jsonb_typeof(_attachments) IS DISTINCT FROM 'array'\n  OR jsonb_array_length(_attachments)>10 THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SAVE_INVALID' USING ERRCODE='22023'; END IF;\n request_digest:=encode(sha256(convert_to(jsonb_build_object('source',_expected_updated_at,'contact',_contact,'connector',_connector,\n  'subject',_subject,'text',_text,'html',_html,'files',_attachments,'time',_send_at,'approval',_approval)::text,'UTF8')),'hex');\n PERFORM pg_advisory_xact_lock(hashtextextended(_save_id::text,32847));\n SELECT * INTO prior_receipt FROM public.paige_audit_log WHERE tenant_id=_tenant AND actor_user_id=_actor\n  AND action='comms.email_draft_saved' AND payload->>'operation_id'=_save_id::text ORDER BY created_at,id LIMIT 1;\n IF prior_receipt.id IS NOT NULL AND (prior_receipt.target_id IS DISTINCT FROM _message_id\n  OR prior_receipt.payload->>'request_digest' IS DISTINCT FROM request_digest) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SAVE_REPLAY_MISMATCH' USING ERRCODE='22023';END IF;\n SELECT * INTO m FROM public.messages WHERE id=_message_id AND tenant_id=_tenant FOR UPDATE;\n IF m.id IS NULL OR m.contact_id IS DISTINCT FROM _contact OR m.channel_type IS DISTINCT FROM 'email'\n  OR m.direction IS DISTINCT FROM 'outbound' OR m.status IS DISTINCT FROM 'draft' OR m.provider_message_id IS NOT NULL\n  OR m.meta ?| ARRAY['comms_email_binding','sales_invoice_binding','growth_sequence_binding','email_campaign_binding'] THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n PERFORM 1 FROM public.clients WHERE id=_contact AND tenant_id=_tenant FOR SHARE;\n IF NOT FOUND THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501';END IF;\n SELECT * INTO source_mailbox FROM public.channel_connectors WHERE id=m.connector_id AND tenant_id=_tenant FOR SHARE;\n IF source_mailbox.id IS NULL OR source_mailbox.active IS DISTINCT FROM true OR source_mailbox.status IS DISTINCT FROM 'active'\n  OR source_mailbox.channel_type IS DISTINCT FROM 'email' OR NOT coalesce(source_mailbox.mailbox_class='shared_support'\n   OR (source_mailbox.mailbox_class='personal' AND source_mailbox.mailbox_owner_user_id=_actor),false) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n IF source_mailbox.mailbox_class='personal' AND _connector IS DISTINCT FROM m.connector_id THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501'; END IF;\n SELECT * INTO chosen FROM public.channel_connectors WHERE id=_connector AND tenant_id=_tenant FOR SHARE;\n IF chosen.id IS NULL OR chosen.active IS DISTINCT FROM true OR chosen.status IS DISTINCT FROM 'active'\n  OR chosen.channel_type IS DISTINCT FROM 'email' OR NOT coalesce(chosen.mailbox_class='shared_support'\n   OR (chosen.mailbox_class='personal' AND chosen.mailbox_owner_user_id=_actor),false) THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_UNAVAILABLE' USING ERRCODE='42501'; END IF;\n IF m.action_id IS NOT NULL OR _approval IS NOT NULL THEN\n  SELECT * INTO ap FROM public.paige_pending_approvals WHERE id=_approval AND tenant_id=_tenant FOR UPDATE;\n  SELECT * INTO act FROM public.paige_actions WHERE id=m.action_id AND tenant_id=_tenant FOR SHARE;\n  IF ap.id IS NULL OR ap.status IS DISTINCT FROM 'pending' OR act.id IS NULL OR act.approval_id IS DISTINCT FROM ap.id\n   OR ap.metadata->>'action_id' IS DISTINCT FROM act.id::text OR act.contact_id IS DISTINCT FROM _contact\n   OR (ap.contact_id IS NOT NULL AND ap.contact_id IS DISTINCT FROM _contact)\n   OR (act.action_kind NOT IN ('owner.lead_followup','client.followup','owner.followup_email')\n    AND NOT coalesce(act.action_kind='comms-draft-reply' AND m.meta->>'source'='comms-draft-reply'\n      AND coalesce(act.payload->>'channel_type','email')='email',false))\n   OR act.action_kind IS NULL OR act.status IS NULL OR act.status NOT IN ('drafted','pending_approval') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_OWNED_FLOW_REQUIRED' USING ERRCODE='42501'; END IF;\n END IF;\n FOR file IN SELECT value FROM jsonb_array_elements(_attachments) LOOP\n  IF jsonb_typeof(file) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(file))<>4\n   OR NOT (file ?& ARRAY['url','name','mime','size']) OR jsonb_typeof(file->'url') IS DISTINCT FROM 'string'\n   OR file->>'url' !~ ('^'||_tenant::text||'/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}-[^/]+$')\n   OR jsonb_typeof(file->'name') IS DISTINCT FROM 'string' OR length(file->>'name') NOT BETWEEN 1 AND 255\n   OR jsonb_typeof(file->'mime') IS DISTINCT FROM 'string' OR length(file->>'mime') NOT BETWEEN 1 AND 255\n   OR jsonb_typeof(file->'size') IS DISTINCT FROM 'number' OR file->>'size' !~ '^[0-9]+$'\n   OR (file->>'size')::bigint NOT BETWEEN 1 AND 10485760\n   OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='comms-attachments' AND o.name=file->>'url') THEN\n   RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_INVALID' USING ERRCODE='22023'; END IF;\n END LOOP;\n IF (SELECT coalesce(sum((value->>'size')::bigint),0) FROM jsonb_array_elements(_attachments))>10485760 THEN\n  RAISE EXCEPTION 'COMMS_EMAIL_ATTACHMENTS_INVALID' USING ERRCODE='22023'; END IF;\n IF m.updated_at IS DISTINCT FROM _expected_updated_at OR prior_receipt.id IS NOT NULL THEN\n  IF prior_receipt.id IS NOT NULL AND m.meta#>>'{comms_draft_save,id}'=_save_id::text AND m.meta#>>'{comms_draft_save,actor}'=_actor::text\n   AND m.meta#>>'{comms_draft_save,digest}'=request_digest AND m.connector_id=_connector\n   AND m.subject=_subject AND m.body_text=_text AND m.body_html=_html AND m.attachments=_attachments\n   AND m.scheduled_for IS NOT DISTINCT FROM _send_at THEN\n   SELECT id INTO receipt_id FROM public.paige_audit_log WHERE id=(m.meta#>>'{comms_draft_save,receipt_id}')::uuid\n    AND tenant_id=_tenant AND actor_user_id=_actor AND target_id=m.id AND action='comms.email_draft_saved'\n    AND payload->>'operation_id'=_save_id::text;\n   IF receipt_id IS NULL THEN RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SAVE_RECEIPT_UNAVAILABLE' USING ERRCODE='55000';END IF;\n   RETURN jsonb_build_object('ok',true,'outcome','draft_saved','message_id',m.id,'updated_at',m.updated_at,'receipt_id',receipt_id,'replayed',true);\n  END IF;\n  RAISE EXCEPTION 'COMMS_EMAIL_DRAFT_SOURCE_CHANGED' USING ERRCODE='40001';\n END IF;\n receipt_id:=gen_random_uuid();\n UPDATE public.messages SET connector_id=_connector,subject=_subject,body_text=_text,body_html=_html,\n  attachments=_attachments,scheduled_for=_send_at,updated_at=clock_timestamp(),\n  sender=CASE WHEN m.connector_id=_connector THEN m.sender ELSE jsonb_build_object('address',lower(btrim(chosen.from_address))) END,\n  meta=coalesce(m.meta,'{}'::jsonb)||jsonb_build_object('comms_draft_save',jsonb_build_object('id',_save_id,'actor',_actor,'digest',request_digest,'receipt_id',receipt_id))\n WHERE id=m.id AND tenant_id=_tenant RETURNING * INTO m;\n INSERT INTO public.paige_audit_log(id,actor_user_id,actor_role,tenant_id,action,target_type,target_id,payload)\n VALUES(receipt_id,_actor,'comms:'||(SELECT role FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=_actor AND status='active' AND role IN ('owner','admin') ORDER BY role LIMIT 1),\n  _tenant,'comms.email_draft_saved','message',m.id,jsonb_build_object('operation_id',_save_id,'request_digest',request_digest,'source_version',_expected_updated_at,'saved_version',m.updated_at));\n RETURN jsonb_build_object('ok',true,'outcome','draft_saved','message_id',m.id,'updated_at',m.updated_at,'receipt_id',receipt_id,'replayed',false);\nEND\n$function$\n","before_md5":null}]$e03_definitions$::jsonb;
 item jsonb; target regprocedure; observed text; original_exists boolean;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(definitions) LOOP
  target:=to_regprocedure('public.'||(item->>'signature'));
  IF target IS NULL THEN
   IF item->>'before_md5' IS NOT NULL THEN RAISE EXCEPTION 'EXP03 saved outcome missing original: %',item->>'signature';END IF;
  ELSE
   SELECT md5(pg_get_functiondef(p.oid)) INTO observed FROM pg_proc p WHERE p.oid=target
    AND pg_get_userbyid(p.proowner)=item->>'owner' AND p.prosecdef=(item->>'definer')::boolean
    AND to_jsonb(p.proconfig)=item->'settings' AND p.proacl::text=item->>'acl';
   IF observed IS NULL OR (observed IS DISTINCT FROM item->>'before_md5' AND observed IS DISTINCT FROM item->>'full_md5')
   THEN RAISE EXCEPTION 'EXP03 saved outcome original drift: %',item->>'signature';END IF;
  END IF;
 END LOOP;
 -- Original authentication/governance/file helpers remain original, never copied or weakened.
 FOR item IN SELECT value FROM jsonb_array_elements('[
  {"signature":"_comms_email_actor(uuid,uuid)","hash":"ff1a928247c3d00c8641b639dacb7fb9","definer":true},
  {"signature":"_comms_email_governance(uuid,uuid,jsonb)","hash":"eb2f2b6e3f58a4843bc330cfad17c25e","definer":true},
  {"signature":"_comms_email_attachment_manifest_ok(uuid,uuid,jsonb)","hash":"9adb7d7f478a85537d0d51e5f75b7b1e","definer":true},
  {"signature":"_comms_email_sendgrid_sender_verified(uuid,text)","hash":"47ffa6378cf940b88275c93913e37d7c","definer":false},
  {"signature":"claim_comms_email_send(uuid,uuid,boolean)","hash":"06c448ffd7a8ce24fa9572fe5f1a66cd","definer":true},
  {"signature":"_comms_email_release_actor(jsonb,uuid)","hash":"ccde8b12ae303148fa53927fd5162912","definer":true},
  {"signature":"_comms_email_reconcilable(jsonb)","hash":"474d5bdb49b2f7b5e233894bd6e433f9","definer":false}
 ]'::jsonb) LOOP
  target:=to_regprocedure('public.'||(item->>'signature'));
  IF target IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=target
   AND md5(pg_get_functiondef(p.oid))=item->>'hash' AND pg_get_userbyid(p.proowner)='postgres'
   AND p.prosecdef=(item->>'definer')::boolean AND p.proconfig=ARRAY['search_path=pg_catalog, public']::text[]
   AND p.proacl::text='{postgres=X/postgres,service_role=X/postgres}')
  THEN RAISE EXCEPTION 'EXP03 saved outcome prerequisite drift: %',item->>'signature';END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(definitions) LOOP
  target:=to_regprocedure('public.'||(item->>'signature'));original_exists:=target IS NOT NULL;
  IF target IS NULL OR md5(pg_get_functiondef(target)) IS DISTINCT FROM item->>'full_md5' THEN
   EXECUTE item->>'definition';
   IF NOT original_exists THEN
    EXECUTE format('ALTER FUNCTION public.%s OWNER TO postgres',item->>'signature');
    EXECUTE format('REVOKE ALL ON FUNCTION public.%s FROM PUBLIC,anon,authenticated,service_role',item->>'signature');
    EXECUTE format('GRANT EXECUTE ON FUNCTION public.%s TO service_role',item->>'signature');
   END IF;
  END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(definitions) LOOP
  target:=to_regprocedure('public.'||(item->>'signature'));
  IF target IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=target
   AND md5(pg_get_functiondef(p.oid))=item->>'full_md5' AND pg_get_userbyid(p.proowner)=item->>'owner'
   AND p.prosecdef=(item->>'definer')::boolean AND to_jsonb(p.proconfig)=item->'settings' AND p.proacl::text=item->>'acl')
  THEN RAISE EXCEPTION 'EXP03 saved outcome final readback drift: %',item->>'signature';END IF;
 END LOOP;
END $exp03_saved_outcome$;
